      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=\"sap:hana:audit\" (action_category IN (\"User Management\",\"User Creation\",\"User Deletion\",\"Permission Grant\",\"Permission Revoke\",\"Password Management\",\"Account Status Change\",\"Password Reset\") OR action_type IN (\"CREATE TABLE\",\"ALTER TABLE\",\"DROP TABLE\",\"CREATE VIEW\",\"ALTER VIEW\",\"DROP VIEW\",\"CREATE SCHEMA\",\"ALTER SCHEMA\",\"DROP SCHEMA\",\"CREATE FUNCTION\",\"ALTER FUNCTION\",\"DROP FUNCTION\",\"CREATE PROCEDURE\",\"ALTER PROCEDURE\",\"DROP PROCEDURE\",\"AUDIT POLICY\",\"CREATE AUDIT POLICY\",\"ALTER AUDIT POLICY\",\"DROP AUDIT POLICY\")) | eval Time = strftime(_time, \"%Y-%m-%d %H:%M:%S\") | sort -_time | head 50 | table Time, executing_user, target_user, action_category, action_type, status, audit_hostname | rename executing_user as \"Operator\", target_user as \"Target\", action_category as \"Category\", action_type as \"Action\", status as \"Status\", audit_hostname as \"Host\"",
