    "ds_windows": {
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=\"XmlWinEventLog\" EventCode IN (4720,4722,4724,4725,4726,4738,4740,4767,4781,4728,4729,4732,4733,4756,4757) | eval Time = strftime(_time, \"%Y-%m-%d %H:%M:%S\") | eval Description = case(EventCode=4720, \"Account Created\", EventCode=4722, \"Account Enabled\", EventCode=4724, \"Password Reset\", EventCode=4725, \"Account Disabled\", EventCode=4726, \"Account Deleted\", EventCode=4738, \"Account Modified\", EventCode=4740, \"Account Locked Out\", EventCode=4767, \"Account Unlocked\", EventCode=4781, \"Account Renamed\", EventCode=4728, \"Added to Global Group\", EventCode=4729, \"Removed from Global Group\", EventCode=4732, \"Added to Local Group\", EventCode=4733, \"Removed from Local Group\", EventCode=4756, \"Added to Universal Group\", EventCode=4757, \"Removed from Universal Group\", 1=1, \"Other\") | sort -_time | head 50 | table Time, EventCode, Description, SubjectUserName, TargetUserName, host | rename EventCode as \"Event\", SubjectUserName as \"Operator\", TargetUserName as \"Target\", host as \"Computer\"",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
