      "type": "ds.search"
    },
    "ds_linux": {
      "options": {
        "query": "`sap_logserv_idx_macro` (sourcetype=\"linux_messages_syslog\" OR sourcetype=\"linux_secure\" OR sourcetype=\"syslog\") (\"COMMAND=\" OR useradd OR usermod OR userdel OR groupadd OR groupmod OR groupdel OR passwd) | eval Time = strftime(_time, \"%Y-%m-%d %H:%M:%S\") | rex field=_raw \"sudo:\\s+(?<sudo_op>\\w+)\\s*:\" | rex field=_raw \"\\((?<paren_op>\\w+)\\)\" | rex field=_raw \"COMMAND=(?<cmd>[^\\s]+(?:\\s[^\\s]+){0,4})\" | eval Operator = coalesce(sudo_op, paren_op, os_user, \"unknown\") | eval Type = case(match(_raw, \"(?i)useradd\"), \"useradd\", match(_raw, \"(?i)usermod\"), \"usermod\", match(_raw, \"(?i)userdel\"), \"userdel\", match(_raw, \"(?i)groupadd\"), \"groupadd\", match(_raw, \"(?i)groupmod\"), \"groupmod\", match(_raw, \"(?i)groupdel\"), \"groupdel\", match(_raw, \"(?i)passwd\\b\"), \"passwd\", match(_raw, \"COMMAND=\"), \"sudo\", 1=1, \"other\") | sort -_time | head 50 | table Time, Operator, Type, cmd, host | rename cmd as \"Command\", host as \"Host\"",
        "queryParameters": {
