 Management\", match(_raw, \"(?i)(groupadd|groupmod|groupdel)\"), \"Group Membership\", match(_raw, \"COMMAND=\"), \"Sudo Command\", 1=1, \"Other\") | eval hr = tonumber(strftime(_time, \"%H\")) | eval dw = strftime(_time, \"%A\") | eval is_after_hours = case(sourcetype=\"sap:hana:audit\", if(is_business_hours=\"false\" OR is_weekend=\"true\", 1, 0), 1=1, if(hr < 7 OR hr > 19 OR match(dw, \"(?i)(saturday|sunday)\"), 1, 0)) | eval Time = strftime(_time, \"%Y-%m-%d %H:%M:%S\") | eval Target = case(sourcetype=\"sap:hana:audit\", target_user, sourcetype=\"XmlWinEventLog\", TargetUserName, 1=1, \"-\") | eval Action = case(sourcetype=\"sap:hana:audit\", action_type, sourcetype=\"XmlWinEventLog\" AND EventCode=4720, \"User Created (EventCode 4720)\", sourcetype=\"XmlWinEventLog\" AND EventCode=4722, \"User Enabled (EventCode 4722)\", sourcetype=\"XmlWinEventLog\" AND EventCode=4724, \"Password Reset (EventCode 4724)\", sourcetype=\"XmlWinEventLog\" AND EventCode=4732, \"Added to Local Group (EventCode 4732)\", sourcetype=\"XmlWinEventLog\", \"EventCode \" . EventCode, 1=1, substr(_raw, 1, 120)) | sort -_time | head 25 | table Time, change_source, category, operator, Target, Action | rename change_source as \"Source\", category as \"Category\", operator as \"Operator\"",
